import{Engine,esc}from'./base.js';export const wordCount=s=>(s.trim().match(/\S+/gu)||[]).length;
export default class Writing extends Engine{constructor(h,c){super(h,c);let w=c.chapter.writing;h.innerHTML=`<div class="writingLayout"><div><p>${esc(c.text(w.prompt))}</p><label>${c.label('Your draft','आपका प्रारूप')}<textarea class="writingDraft" spellcheck="true" placeholder="${c.dual('Write in your own words…','अपने शब्दों में लिखें…')}"></textarea></label><p class="wordCount" role="status"></p><button class="showModel">${c.label('Show model','आदर्श उत्तर देखें')}</button><div class="writingModel" hidden>${c.H({en:'Model Answer',hi:'आदर्श उत्तर'},3)}<p>${esc(c.text(w.model))}</p></div></div><aside class="writingGuide">${c.H({en:'Structure Guide',hi:'संरचना मार्गदर्शिका'},3)}<ol>${w.guide.map(g=>`<li>${esc(c.text(g))}</li>`).join('')}</ol><p>${c.dual('Compare ideas and organisation; this editor does not grade your writing.','विचारों और संगठन की तुलना करें; यह संपादक लेखन का मूल्यांकन नहीं करता।')}</p></aside></div>`;let draft=h.querySelector('textarea');draft.value=c.draft||'';this.on(draft,'input',()=>{c.saveDraft(draft.value);this.render()});this.on(h.querySelector('.showModel'),'click',()=>{h.querySelector('.writingModel').hidden=false;this.metrics.model=true;this.emit(c.dual('Compare your answer with the model.','अपने उत्तर की आदर्श उत्तर से तुलना करें।'))});this.render()}render(){let n=wordCount(this.host.querySelector('textarea').value);this.metrics.words=n;this.host.querySelector('.wordCount').textContent=this.ctx.dual('Word count','शब्द संख्या')+': '+n;this.emit(this.ctx.dual('Draft saved on this device.','प्रारूप इस उपकरण पर सुरक्षित है।'))}}
